(function(root){
const data=typeof module!=='undefined'?require('./levels.js'):root.SnackLevels;
const names=['草莓','布丁','花椰菜','葡萄','糖果','甜甜圈'];
function rng(seed){return ()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296;};}
function config(l){if(!Number.isInteger(l)||l<1||l>100)throw Error('Invalid level');const d=data[l-1],cols=7,rows=d.layout.length,size=cols*rows;let cfg={...d,l,cols,rows,size,mask:d.layout.join('').split('').map(c=>c==='#')};for(let k of ['ice','boxes','jelly']){cfg[k]=Array(size).fill(0);for(let [i,n] of d[k])cfg[k][i]=n;}return cfg;}
class Game{
constructor(l,seed=Date.now()){this.cfg=config(l);this.rand=rng(seed);this.b=Array(this.cfg.size).fill(-1);this.ice=[...this.cfg.ice];this.boxes=[...this.cfg.boxes];this.jelly=[...this.cfg.jelly];this.moves=this.cfg.moves;this.score=0;this.got=0;this.fillClean();}
active(i){return i>=0&&i<this.cfg.size&&this.cfg.mask[i]&&!this.boxes[i];}
fillClean(){const w=this.cfg.cols;for(let i=0;i<this.cfg.size;i++)if(this.active(i)){let allowed=Array.from({length:this.cfg.colors},(_,v)=>v).filter(v=>!(i%w>1&&this.active(i-1)&&this.active(i-2)&&this.b[i-1]===v&&this.b[i-2]===v)&&!(i>=w*2&&this.active(i-w)&&this.active(i-w*2)&&this.b[i-w]===v&&this.b[i-w*2]===v));this.b[i]=allowed[this.rand()*allowed.length|0];}if(!this.legal().length)this.shuffle();}
match(){const w=this.cfg.cols,s=this.cfg.size;let out=new Set;for(let i=0;i<s;i++){if(!this.active(i)||this.b[i]<0)continue;for(let delta of [1,w]){if(delta===1&&i%w>w-3||delta===w&&i+2*w>=s)continue;let ids=[i,i+delta,i+2*delta];if(ids.every(j=>this.active(j)&&this.b[j]===this.b[i]))ids.forEach(j=>out.add(j));}}return [...out];}
adj(a,b){const w=this.cfg.cols;return a>=0&&b>=0&&a<this.cfg.size&&b<this.cfg.size&&(Math.abs(a-b)===w||(Math.abs(a-b)===1&&Math.floor(a/w)===Math.floor(b/w)));}
swap(a,b){[this.b[a],this.b[b]]=[this.b[b],this.b[a]];}
legal(){let out=[];for(let a=0;a<this.cfg.size;a++)for(let b of [a+1,a+this.cfg.cols])if(this.active(a)&&this.active(b)&&this.adj(a,b)&&this.b[a]!==this.b[b]){this.swap(a,b);let m=this.match();this.swap(a,b);if(m.length)out.push([a,b]);}return out;}
shuffle(){for(let k=0;k<1000;k++){this.b.fill(-1);const w=this.cfg.cols;for(let i=0;i<this.cfg.size;i++)if(this.active(i)){let allowed=Array.from({length:this.cfg.colors},(_,v)=>v).filter(v=>!(i%w>1&&this.active(i-1)&&this.active(i-2)&&this.b[i-1]===v&&this.b[i-2]===v)&&!(i>=w*2&&this.active(i-w)&&this.active(i-w*2)&&this.b[i-w]===v&&this.b[i-w*2]===v));this.b[i]=allowed[this.rand()*allowed.length|0];}if(this.legal().length)return;}throw Error('Unable to shuffle');}
clear(ids){let hit=new Set(ids),near=new Set;const w=this.cfg.cols;for(let i of hit){if(i<0||i>=this.cfg.size||!this.cfg.mask[i])continue;if(this.boxes[i]){this.boxes[i]--;continue;}if(!this.active(i)||this.b[i]<0)continue;if(this.b[i]===this.cfg.food)this.got++;this.score+=60;if(this.ice[i])this.ice[i]--;else if(this.jelly[i])this.jelly[i]--;this.b[i]=-1;for(let j of [i-w,i+w,i-1,i+1])if(this.adj(i,j))near.add(j);}for(let i of near)if(this.boxes[i]&&!hit.has(i))this.boxes[i]--;}
fall(){const w=this.cfg.cols;for(let c=0;c<w;c++){let segment=[];const flush=()=>{let values=segment.map(i=>this.b[i]).filter(v=>v>=0);for(let k=segment.length-1;k>=0;k--)this.b[segment[k]]=values.length?values.pop():this.rand()*this.cfg.colors|0;segment=[];};for(let r=0;r<this.cfg.rows;r++){let i=r*w+c;if(this.active(i))segment.push(i);else flush();}flush();}}
won(){return this.got>=this.cfg.target&&this.score>=this.cfg.scoreTarget&&!this.ice.some(Boolean)&&!this.boxes.some(Boolean)&&!this.jelly.some(Boolean);}
}root.Snack={Game,config,names,rng};if(typeof module!=='undefined')module.exports=root.Snack;
})(typeof window==='undefined'?globalThis:window);
